export function instalmentStatusLabel(status: InstalmentStatus): string {
  return INSTALMENT_STATUS_LABEL[status];
}

// Money from the server is already to the cent (whole yen for yen), so the number shown is exact:
// $1,234.50, €1,234.50, £1,234.50, ¥1,235, CHF 1,234.50.
export function money(amount: string, currency: Currency = 'USD'): string {
  const value = Number(amount);
  const shown = NUMBER[decimalsOf(currency)].format(Math.abs(value));
  return (value < 0 ? '-' : '') + SYMBOL[currency] + shown;
}

// The symbol amounts in the currency are entered in, for form labels.
export function symbolOf(currency: Currency): string {
  return SYMBOL[currency].trim();
}

// A positive decimal with at most two decimals, e.g. 1, 1.5 or 12.35. The server applies the same rules.
export const TWO_DECIMALS = /^\d+(\.\d{1,2})?$/;

  // For a client billed in another currency, the exchange difference in US dollars of the payments
  // applied to it (negative for a loss); null for a dollar invoice.
  fxDifference: string | null;
  // The day (yyyy-mm-dd) it was written off as a bad debt, null when it was not; everything it still
  // owed then, late charges and retention included, is in `writtenOff`.
  writtenOffOn: string | null;
  // Whether it is reverse charged: its client is registered (a valid tax number) outside the
  // workspace's home region and accounts for the tax itself, so no line is taxed.
  reverseCharge: boolean;
  // What the amount after its discounts falls short of the workspace's minimum charge, added to the
  // invoice and taxed at the client's rate; "0.00" when there is none.
  minimumCharge: string;
}
